create table private.builtin_scenario_secrets (
  scenario_id text primary key,
  instructor_notes text not null,
  client_responses jsonb not null,
  constraint builtin_scenario_secrets_responses_check
    check (client_responses = '{}'::jsonb or private.valid_client_responses(1, client_responses))
);

alter table private.builtin_scenario_secrets enable row level security;
revoke all on table private.builtin_scenario_secrets from public, anon, authenticated;

insert into private.builtin_scenario_secrets (scenario_id, instructor_notes, client_responses) values
  ('sc-net-f26-01', 'SETUP: Pod at documented baseline; label devices R1/R2/S1/S2 and provide two known-good laptops. No configuration changes required.
ROTATION: Cohort discovery, then teams of three rotate lead/communication, physical identification, and evidence roles. Every student must physically trace and identify at least one connection.
DIAGNOSTIC BRANCHES: A missing label is resolved by tracing; damaged power/network hardware is an escalation, not a repair.
VERIFY: Student identifies every device, console path, endpoint path, power isolation point, and safety equipment.
RESET: Return cables to labeled storage positions; power state matches baseline; chairs and floor paths clear.
PRINTED SERVICE LOG: Pod diagram, device/port identifiers, one safety observation, one escalation boundary, instructor initials.
SCOPE BOUNDARY: VLAN and static-route configuration are not assessed or authorized.', '{"scope":{"response":"Only the equipment named in this ticket is affected.","quality":"exact"},"timing_change":{"response":"The issue was noticed during today''s setup; no other change is confirmed.","quality":"exact"},"symptom_error":{"response":"There is no additional error message beyond the symptom in the ticket.","quality":"exact"},"environment_equipment":{"response":"Use the assigned Cisco pod and the two designated lab laptops.","quality":"exact"},"prior_troubleshooting":{"response":"No troubleshooting was attempted before the ticket was opened.","quality":"exact"},"impact_urgency":{"response":"This blocks the assigned lab station, but no production service is affected.","quality":"exact"}}'::jsonb),
  ('sc-net-f26-02', 'SETUP: One known-good reference cable; materials for two student cables; assign equivalent tester-fault cards (open, reversal, split pair).
ROTATION: Each student must terminate or reterminate at least one end and personally run/interpret one tester cycle.
