insert into private.builtin_scenario_secrets (scenario_id, instructor_notes, client_responses) values
  ('sc-hw-01', 'Physical task: Unbox the PC Parts kit and identify each major component category at a glance — PSU, motherboard, RAM, CPU + cooler, GPU, storage. This is recognition, not deep analysis (that''s Week 3). Cover lab orientation and ESD basics, and introduce the Field Journal as the ongoing documentation habit for the quarter. Field Journal: inventory table by category with quantities, one labeled photo/sketch per component type.', '{}'::jsonb),
  ('sc-hw-02', 'Physical task: Identify and label every port and connector type present on the motherboards, PSUs, and drives in the parts kit — SATA data/power, 24-pin ATX, CPU 4/8-pin, PCIe power, USB headers, front-panel headers, video outputs. Match each connector to its cable and its correct use — this is also a good moment to (gently) confirm or debunk Sam''s confident guess. Field Journal: connector reference sheet with photos/sketches and what each one powers or carries.', '{}'::jsonb),
  ('sc-hw-03', 'Physical task: Full motherboard analysis using the ASRock boards from inventory — identify CPU socket type, RAM slot count/channels, expansion slot types (PCIe x16/x1), chipset, form factor, rear I/O. Visually inspect every board for damage (bent pins, bulging capacitors, burn marks) before any of them go into Week 5''s build. Field Journal: labeled motherboard diagram calling out every major component.', '{}'::jsonb),
  ('sc-hw-04', 'Physical task: Access BIOS/UEFI on available bench-capable systems (this quarter''s own builds don''t exist until next week — use existing stock). Record all settings found, correct as needed, note anything that would block a clean OS install later. Field Journal: settings audit table per machine, changes made with rationale.', '{}'::jsonb),
  ('sc-hw-11', 'Bonus/enrichment — not part of the required 10-week sequence, doesn''t map to a textbook chapter. Assign as extra credit, an open-lab activity, or filler for early finishers. Physical task: flash Raspberry Pi OS to a microSD card, boot the Pi, configure headless access (SSH + a static or reserved IP) with no monitor attached. 44 units in stock — one per student is realistic. Stretch step: connect the included Crickit add-on board and confirm it''s detected. Field Journal: imaging steps, headless connection method used, one command run successfully over SSH to prove access.', '{}'::jsonb),
  ('sc-cy-01', 'Physical task: Security baseline audit on assigned workstation — OS patch level, Windows Defender status, open ports via netstat. Document current security posture and any misconfigurations found. Field Journal: security baseline checklist with pass/fail for each item.', '{}'::jsonb),
  ('sc-cy-02', 'Physical task: Use Nmap to scan the lab subnet. Document all discovered hosts, open ports, and services. Flag any unexpected findings. Field Journal: Nmap output table — host, IP, open ports, services. Note anything that warrants further investigation.', '{}'::jsonb),
  ('sc-cy-03', 'Physical task: Audit local password policy on lab machine (min length, complexity, lockout thresholds). Compare against NIST SP 800-63B recommendations. Apply recommended changes. Field Journal: before/after policy settings table, summary of NIST guidelines and rationale for each change.', '{}'::jsonb),
  ('sc-cy-04', 'Controlled lab exercise with Hak5 WiFi Pineapple — perform passive recon scan, identify probe requests from devices, document what an attacker could observe. Field Journal: what data was visible, what the defensive implications are, and what specific mitigations would address the risk.', '{}'::jsonb),
  ('sc-cy-05', 'Physical task: Run vulnerability scan (OpenVAS, Nessus, or equivalent) against designated lab target VM. Categorize findings by severity (Critical/High/Medium/Low). Field Journal: top 5 findings with CVE numbers, severity ratings, and specific remediation steps for each.', '{}'::jsonb),
  ('sc-cy-06', 'Instructor stages a simulated malware alert on a lab machine (unusual processes, outbound connections visible in netstat). Students isolate the machine, collect evidence (process list, netstat, event logs), and write an incident response ticket. Field Journal: IR checklist — contain, collect, analyze, report. Reference PICERL framework.', '{}'::jsonb),
  ('sc-cy-07', 'Controlled lab exercise with Hak5 USB Rubber Ducky — execute a benign payload on lab machine, document what the attack accomplished and how fast it executed. Field Journal: attack timeline (from plug-in to completion), what defenses would have stopped it (USB policy, endpoint protection), recommended policy changes.', '{}'::jsonb),
  ('sc-cy-08', 'Physical task: Review Windows Firewall rules on lab machine. Identify overly permissive or unnecessary rules. Apply a default-deny outbound rule for a designated test application. Field Journal: before/after firewall rule table with justification for each change made.', '{}'::jsonb),
  ('sc-cy-09', 'Red vs Blue exercise: half class is red team (offensive), half is blue team managing the incident queue. Red team uses tools covered this quarter with instructor-defined scope. Blue team detects, documents, contains, reports. Field Journal: after-action report — what attacks succeeded, what was detected, what was missed, recommendations.', '{}'::jsonb),
  ('sc-cy-10', 'Capstone: Teams harden the complete lab environment built across all three courses. OS hardening, network segmentation, access controls, monitoring. Every change documented as a ticket. Field Journal: complete hardening checklist with evidence for each control, lessons learned across all three courses, final security posture statement.', '{}'::jsonb)
on conflict (scenario_id) do update set instructor_notes=excluded.instructor_notes;

create or replace function public.get_builtin_scenario_instructor_notes()
returns table (scenario_id text, instructor_notes text)
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not (select private.is_admin()) then
    raise exception 'admin_required' using errcode='42501';
  end if;
  return query
    select secret.scenario_id, secret.instructor_notes
    from private.builtin_scenario_secrets secret
    order by secret.scenario_id;
end;
$$;
revoke all on function public.get_builtin_scenario_instructor_notes() from public, anon, authenticated;
grant execute on function public.get_builtin_scenario_instructor_notes() to authenticated;

create or replace function public.create_lab_assignment_with_tickets(p_class_id uuid,p_week_label text,p_tickets jsonb)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_assignment_id uuid; v_ticket jsonb; v_ticket_id uuid; v_limit integer; v_responses jsonb; v_incident_id uuid;
begin
  if not (select private.is_admin()) then raise exception 'admin_required' using errcode='42501'; end if;
  if jsonb_typeof(p_tickets)<>'array' or jsonb_array_length(p_tickets)=0 then raise exception 'tickets_required'; end if;
  insert into public.lab_assignments(class_id,week_label,assigned_by) values(p_class_id,btrim(p_week_label),auth.uid()) returning id into v_assignment_id;
  for v_ticket in select value from jsonb_array_elements(p_tickets) item(value) loop
    v_limit:=coalesce((v_ticket->>'inquiry_limit')::integer,0);
    select secret.client_responses into v_responses
    from private.builtin_scenario_secrets secret
    where secret.scenario_id=v_ticket->>'scenario_id';
    if not found then v_responses:=coalesce(v_ticket->'client_responses','{}'::jsonb); end if;
    v_incident_id:=null;
    if v_limit not between 0 and 3 then raise exception 'invalid_inquiry_limit'; end if;
    if not private.valid_client_responses(v_limit,v_responses) then raise exception 'incomplete_client_responses'; end if;
    if nullif(v_ticket->>'team_key','') is not null then
      insert into public.team_incidents(assignment_id,team_key,team_name,color_name,color_hex,title,description)
      values(v_assignment_id,v_ticket->>'team_key',v_ticket->>'team_name',v_ticket->>'color_name',v_ticket->>'color_hex',v_ticket->>'title',v_ticket->>'description')
      on conflict(assignment_id,team_key) do update set
        team_name=excluded.team_name,color_name=excluded.color_name,color_hex=excluded.color_hex,
        title=excluded.title,description=excluded.description
      returning id into v_incident_id;
    end if;
    insert into public.assigned_tickets(assignment_id,student_id,group_tag,scenario_id,course_id,week,title,description,priority,status,inquiry_limit,team_incident_id)
    values(v_assignment_id,(v_ticket->>'student_id')::uuid,nullif(v_ticket->>'group_tag',''),v_ticket->>'scenario_id',v_ticket->>'course_id',(v_ticket->>'week')::integer,v_ticket->>'title',v_ticket->>'description',v_ticket->>'priority','New',v_limit,v_incident_id)
    returning id into v_ticket_id;
    if v_limit>0 then insert into private.assigned_ticket_scripts values(v_ticket_id,v_responses); end if;
    if v_incident_id is not null and nullif(v_ticket->>'team_role','') is not null then
      insert into public.team_contributions(assigned_ticket_id,student_id,team_role,contribution)
      values(v_ticket_id,(v_ticket->>'student_id')::uuid,v_ticket->>'team_role',null);
    end if;
  end loop; return v_assignment_id;
end; $$;
revoke all on function public.create_lab_assignment_with_tickets(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.create_lab_assignment_with_tickets(uuid,text,jsonb) to authenticated;
